"""Exact evaluation of the class-group dial by convolution."""

from __future__ import annotations

from itertools import product
from math import log
from typing import Dict, List, Sequence, Tuple

Elem = Tuple[int, ...]
Profile = Dict[Elem, float]


def binary_entropy(x: float) -> float:
    """h(x) = -x log x - (1-x) log(1-x) in nats, with h(0) = h(1) = 0."""
    if x <= 0.0 or x >= 1.0:
        return 0.0
    return -x * log(x) - (1.0 - x) * log(1.0 - x)


def group_elements(moduli: Sequence[int]) -> List[Elem]:
    """All elements of Z/m_1 x ... x Z/m_r."""
    return [tuple(e) for e in product(*(range(m) for m in moduli))]


def add(a: Elem, b: Elem, moduli: Sequence[int]) -> Elem:
    return tuple((x + y) % m for x, y, m in zip(a, b, moduli))


def sub(a: Elem, b: Elem, moduli: Sequence[int]) -> Elem:
    return tuple((x - y) % m for x, y, m in zip(a, b, moduli))


def mean_rate(moduli: Sequence[int], s: Profile) -> float:
    """The count statistic: the uniform average of the profile."""
    elts = group_elements(moduli)
    return sum(s[a] for a in elts) / len(elts)


def convolve(moduli: Sequence[int], t: Profile, s: Profile) -> Profile:
    """Averaged convolution (t * s)(c) = |G|^{-1} sum_a t(a) s(c - a)."""
    elts = group_elements(moduli)
    n = len(elts)
    return {c: sum(t[a] * s[sub(c, a, moduli)] for a in elts) / n for c in elts}


def fork_power(moduli: Sequence[int], s: Profile, k: int) -> Profile:
    """The k-fold convolution power s^{*k}; k = 2 is the semiprime no-fork profile."""
    if k < 1:
        raise ValueError("k must be at least 1")
    out = dict(s)
    for _ in range(k - 1):
        out = convolve(moduli, out, s)
    return out


def dial(moduli: Sequence[int], s: Profile, k: int = 2) -> float:
    """Phi_k(s) = h(mean^k) - avg_c h(s^{*k}(c)).  k = 2 is the semiprime dial T."""
    elts = group_elements(moduli)
    m = mean_rate(moduli, s)
    cond = fork_power(moduli, s, k)
    return binary_entropy(m ** k) - sum(binary_entropy(cond[c]) for c in elts) / len(elts)


OR_CAP: float = binary_entropy(0.25) - 0.5 * binary_entropy(0.5)

if __name__ == "__main__":
    moduli = (12,)
    K = {a for a in group_elements(moduli) if a[0] % 2 == 0}
    indicator: Profile = {a: (1.0 if a in K else 0.0) for a in group_elements(moduli)}
    print(f"cap                 = {OR_CAP:.10f} nats")
    print(f"dial of 1_K on Z/12 = {dial(moduli, indicator):.10f} nats")
    print(f"mean rate           = {mean_rate(moduli, indicator):.4f}")

"""Multiplier randomisation and the washout decision procedure."""

from __future__ import annotations

from itertools import product
from math import log
from typing import Dict, Iterable, List, Sequence, Tuple

Elem = Tuple[int, ...]
Profile = Dict[Elem, float]


def binary_entropy(x: float) -> float:
    if x <= 0.0 or x >= 1.0:
        return 0.0
    return -x * log(x) - (1.0 - x) * log(1.0 - x)


def elements(moduli: Sequence[int]) -> List[Elem]:
    return [tuple(e) for e in product(*(range(m) for m in moduli))]


def add(a: Elem, b: Elem, moduli: Sequence[int]) -> Elem:
    return tuple((x + y) % m for x, y, m in zip(a, b, moduli))


def sub(a: Elem, b: Elem, moduli: Sequence[int]) -> Elem:
    return tuple((x - y) % m for x, y, m in zip(a, b, moduli))


def subgroup_generated(moduli: Sequence[int], gens: Iterable[Elem]) -> List[Elem]:
    """Closure of a generating set under the group law (breadth-first)."""
    ident = tuple(0 for _ in moduli)
    seen = {ident}
    frontier = [ident]
    gens = list(gens)
    while frontier:
        nxt: List[Elem] = []
        for x in frontier:
            for g in gens:
                y = add(x, g, moduli)
                if y not in seen:
                    seen.add(y)
                    nxt.append(y)
        frontier = nxt
    return sorted(seen)


def mix(moduli: Sequence[int], H: Sequence[Elem], s: Profile) -> Profile:
    """(mix_H s)(a) = |H|^{-1} sum_{g in H} s(g + a): the randomised profile."""
    return {a: sum(s[add(g, a, moduli)] for g in H) / len(H) for a in elements(moduli)}


def mean_rate(moduli: Sequence[int], s: Profile) -> float:
    elts = elements(moduli)
    return sum(s[a] for a in elts) / len(elts)


def dial(moduli: Sequence[int], s: Profile) -> float:
    elts = elements(moduli)
    n = len(elts)
    m = mean_rate(moduli, s)
    cond = {c: sum(s[a] * s[sub(c, a, moduli)] for a in elts) / n for c in elts}
    return binary_entropy(m * m) - sum(binary_entropy(cond[c]) for c in elts) / n


def index_of(moduli: Sequence[int], H: Sequence[Elem]) -> int:
    return len(elements(moduli)) // len(H)


def survives_washout(moduli: Sequence[int], H: Sequence[Elem]) -> bool:
    """Parity criterion: a maximal channel survives randomisation over H iff [G:H] is even."""
    return index_of(moduli, H) % 2 == 0


def washout_report(moduli: Sequence[int], gens: Sequence[Elem]) -> Dict[str, float]:
    """Full diagnosis for the multiplier group generated by `gens` acting on the maximiser."""
    elts = elements(moduli)
    K = [a for a in elts if a[0] % 2 == 0]          # an index-two subgroup when moduli[0] is even
    indicator: Profile = {a: (1.0 if a in set(K) else 0.0) for a in elts}
    H = subgroup_generated(moduli, gens)
    mixed = mix(moduli, H, indicator)
    return {
        "multiplier_order": float(len(H)),
        "index": float(index_of(moduli, H)),
        "survives": 1.0 if survives_washout(moduli, H) else 0.0,
        "mean_before": mean_rate(moduli, indicator),
        "mean_after": mean_rate(moduli, mixed),
        "dial_before": dial(moduli, indicator),
        "dial_after": dial(moduli, mixed),
    }


if __name__ == "__main__":
    for gens in ([(0,)], [(4,)], [(3,)], [(1,)]):
        rep = washout_report((12,), gens)
        print(f"H = <{gens[0][0]:>2}>  |H| = {rep['multiplier_order']:>4.0f}"
              f"  [G:H] = {rep['index']:>4.0f}"
              f"  mean {rep['mean_before']:.3f} -> {rep['mean_after']:.3f}"
              f"  dial {rep['dial_before']:.6f} -> {rep['dial_after']:.6f}")

"""The budgeted-adversary threshold via the 2-adic valuation of the class number."""

from __future__ import annotations

from typing import Dict, List, Tuple


def two_adic_valuation(n: int) -> int:
    """v_2(n): the exponent of 2 in n.  Requires n >= 1."""
    if n < 1:
        raise ValueError("n must be positive")
    v = 0
    while n % 2 == 0:
        n //= 2
        v += 1
    return v


def two_part(n: int) -> int:
    """tau(G) = 2^{v_2(|G|)}: the order of a Sylow 2-subgroup."""
    return 1 << two_adic_valuation(n)


def channel_survives_budget(group_order: int, budget: int) -> bool:
    """A maximal channel survives every multiplier group of order <= budget iff budget < tau(G)."""
    return budget < two_part(group_order)


def largest_safe_budget(group_order: int) -> int:
    """The largest budget an adversary may spend without being able to destroy the channel."""
    return two_part(group_order) - 1


def threshold_report(group_order: int) -> Dict[str, int]:
    return {
        "group_order": group_order,
        "v2": two_adic_valuation(group_order),
        "two_part": two_part(group_order),
        "largest_safe_budget": largest_safe_budget(group_order),
        "cheapest_fatal_multiplier_group": two_part(group_order),
    }


def unit_group_thresholds(primes: List[int]) -> List[Tuple[int, int, int]]:
    """For each odd prime p, the order p-1 of (Z/p)^* and its surviving-budget threshold."""
    return [(p, p - 1, two_part(p - 1)) for p in primes]


if __name__ == "__main__":
    for p, order, thr in unit_group_thresholds([11, 13, 17, 19, 23, 29, 31, 37, 41]):
        print(f"(Z/{p:>2})^*: |G| = {order:>2},  2-part = {thr:>2},"
              f"  safe budgets B <= {thr - 1}")
    print()
    for order in [2 * 3 * 5 * 7 * 11 * 13, 1 << 10, 12, 40]:
        rep = threshold_report(order)
        print(f"|G| = {rep['group_order']:>6}  ->  threshold {rep['two_part']:>4}"
              f"  (safe budgets up to {rep['largest_safe_budget']})")
